/**
 * Generates the Effect schemas for the plugin protocol from its JSON Schema
 * files, so this repo keeps no hand-written copy of the protocol.
 *
 *   bun scripts/plugin-types.ts           write packages/core/src/plugin/generated/*.ts
 *   bun scripts/plugin-types.ts --check   exit 1 if a generated file is out of date
 *
 * Each `plugin/<name>.schema.json` becomes `generated/<name>.ts`, one export
 * per `$defs` entry. A `$ref` into another schema file
 * (`base.schema.json#/$defs/x`) is resolved by copying that file's
 * definitions in under a `Base` prefix.
 */
import { readFileSync, writeFileSync } from "node:fs"
import path from "node:path"
import { type JsonSchema, Predicate, SchemaRepresentation } from "effect"

const ROOT = path.resolve(import.meta.dir, "..")
const SCHEMAS = ["base"] as const
const OUT_DIR = path.join(ROOT, "packages/core/src/plugin/generated")

interface SchemaFile {
  readonly $id: string
  readonly $defs: Record<string, JsonSchema.JsonSchema>
}

function readSchema(name: string): SchemaFile {
  const file = path.join(ROOT, "plugin", `${name}.schema.json`)
  const parsed: unknown = JSON.parse(readFileSync(file, "utf8"))
  if (!Predicate.isObject(parsed) || !("$id" in parsed) || !Predicate.isString(parsed.$id)) {
    throw new Error(`${file}: expected an object with a string $id`)
  }
  const defs = "$defs" in parsed ? parsed.$defs : undefined
  if (!Predicate.isObject(defs)) throw new Error(`${file}: expected a $defs object`)
  const $defs: Record<string, JsonSchema.JsonSchema> = {}
  for (const [def, schema] of Object.entries(defs)) {
    if (!Predicate.isObject(schema)) throw new Error(`${file}: $defs.${def} is not an object`)
    $defs[def] = { ...schema }
  }
  return { $id: parsed.$id, $defs }
}

const prefixed = (prefix: string, name: string) =>
  `${prefix}${name.charAt(0).toUpperCase()}${name.slice(1)}`

/** Rewrites `<other $id>#/$defs/x` to a local ref to the copied definition. */
function rewriteRefs(value: unknown, others: ReadonlyMap<string, string>): unknown {
  if (Array.isArray(value)) return value.map((item) => rewriteRefs(item, others))
  if (!Predicate.isObject(value)) return value
  const out: JsonSchema.JsonSchema = {}
  for (const [key, child] of Object.entries(value)) {
    if (key === "$ref" && typeof child === "string" && !child.startsWith("#")) {
      const [file, pointer] = child.split("#")
      const prefix = file === undefined ? undefined : others.get(file)
      const name = pointer?.replace(/^\/\$defs\//, "")
      if (prefix === undefined || name === undefined) {
        throw new Error(`unresolved $ref ${child}`)
      }
      out[key] = `#/$defs/${prefixed(prefix, name)}`
    } else {
      out[key] = rewriteRefs(child, others)
    }
  }
  return out
}

function generate(name: string): string {
  const own = readSchema(name)
  const others = new Map<string, string>()
  const definitions: Record<string, JsonSchema.JsonSchema> = {}
  if (name !== "base") {
    const base = readSchema("base")
    others.set(base.$id, "Base")
    for (const [def, schema] of Object.entries(base.$defs)) {
      definitions[prefixed("Base", def)] = schema
    }
  }
  for (const [def, schema] of Object.entries(own.$defs)) {
    const rewritten = rewriteRefs(schema, others)
    if (Predicate.isObject(rewritten)) definitions[def] = { ...rewritten }
  }
  const [firstRoot, ...otherRoots] = Object.keys(own.$defs).map((def) => ({
    $ref: `#/$defs/${def}`,
  }))
  if (firstRoot === undefined) throw new Error(`plugin/${name}.schema.json has no $defs`)
  const document: JsonSchema.MultiDocument<"draft-2020-12"> = {
    dialect: "draft-2020-12",
    schemas: [firstRoot, ...otherRoots],
    definitions,
  }
  const schemas = SchemaRepresentation.fromJsonSchemaMultiDocument(document)
  const [first, ...rest] = schemas.map((schema) => schema.ast)
  if (first === undefined) throw new Error(`plugin/${name}.schema.json produced no schema`)
  const code = SchemaRepresentation.toCodeDocument(
    SchemaRepresentation.toRepresentations([first, ...rest]),
  )
  if (Object.keys(code.references.recursives).length > 0) {
    throw new Error(`plugin/${name}.schema.json: recursive definitions are not supported`)
  }

  const lines = [
    `// Generated by scripts/plugin-types.ts from plugin/${name}.schema.json. Do not edit:`,
    `// change the schema and run \`bun scripts/plugin-types.ts\`.`,
    `import { Schema } from "effect"`,
    "",
  ]
  for (const { $ref, code: def } of code.references.nonRecursives) {
    lines.push(
      `export const ${$ref} = ${def.runtime}`,
      `export type ${$ref} = typeof ${$ref}.Type`,
      "",
    )
  }
  return format(lines.join("\n"), `${name}.ts`)
}

function format(source: string, filename: string): string {
  const bin = path.join(ROOT, "node_modules/.bin/oxfmt")
  const result = Bun.spawnSync([bin, `--stdin-filepath=${filename}`], {
    cwd: ROOT,
    stdin: new TextEncoder().encode(source),
  })
  if (result.exitCode !== 0) {
    throw new Error(`oxfmt failed on ${filename}: ${result.stderr.toString()}`)
  }
  return result.stdout.toString()
}

/** The generated files that differ from what the schemas produce now. */
export function outdated(): string[] {
  return SCHEMAS.filter((name) => {
    const file = path.join(OUT_DIR, `${name}.ts`)
    let current = ""
    try {
      current = readFileSync(file, "utf8")
    } catch {
      return true
    }
    return current !== generate(name)
  }).map((name) => path.relative(ROOT, path.join(OUT_DIR, `${name}.ts`)))
}

if (import.meta.main) {
  if (process.argv.includes("--check")) {
    const stale = outdated()
    if (stale.length > 0) {
      console.error(`Out of date: ${stale.join(", ")}. Run: bun scripts/plugin-types.ts`)
      process.exit(1)
    }
  } else {
    for (const name of SCHEMAS) writeFileSync(path.join(OUT_DIR, `${name}.ts`), generate(name))
  }
}
